package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="messages")
public class Message { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="sender_id") private Long senderId; @Column(name="team_id") private Long teamId; @Column(name="event_id") private Long eventId; @Column(length=5000) private String content; @Column(name="sent_at") private LocalDateTime sentAt = LocalDateTime.now(); @Column(name="is_global") private boolean globalMessage = true; public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getSenderId(){return senderId;} public void setSenderId(Long senderId){this.senderId=senderId;} public Long getTeamId(){return teamId;} public void setTeamId(Long teamId){this.teamId=teamId;} public Long getEventId(){return eventId;} public void setEventId(Long eventId){this.eventId=eventId;} public String getContent(){return content;} public void setContent(String content){this.content=content;} public LocalDateTime getSentAt(){return sentAt;} public void setSentAt(LocalDateTime sentAt){this.sentAt=sentAt;} public boolean isGlobalMessage(){return globalMessage;} public void setGlobalMessage(boolean globalMessage){this.globalMessage=globalMessage;} }
